"""Thin batch handoff to the existing full matcher and unchanged sandboxed entries."""
from pathlib import Path
import argparse, concurrent.futures, importlib.util, json, os, subprocess, sys, time

def main():
    p=argparse.ArgumentParser()
    p.add_argument("--library",type=Path,required=True)
    p.add_argument("--requests",type=Path,required=True)
    p.add_argument("--workers",type=int,choices=[1,2,4,8],default=1)
    p.add_argument("--result",type=Path,required=True)
    p.add_argument("--lane-root",type=Path,help="Explicit authorized batch root with one independent subdirectory per lane")
    p.add_argument("--stream-lanes",action="store_true",help="Each persistent lane matches and delivers its own task stream")
    a=p.parse_args()
    began=time.perf_counter()
    spec=importlib.util.spec_from_file_location("original_flow_matcher",a.library/"scripts/match_flow.py")
    matcher=importlib.util.module_from_spec(spec);spec.loader.exec_module(matcher)
    registry=json.loads(matcher.DEFAULT_REGISTRY.read_text(encoding="utf-8-sig"))
    paths=json.loads(a.requests.read_text(encoding="utf-8-sig"))
    if not isinstance(paths,list) or not paths: raise ValueError("Nonempty request path list required")
    requests=[json.loads(Path(f).read_text(encoding="utf-8-sig")) for f in paths]
    workspaces=[os.path.normcase(str(Path(r["workspace"]).resolve(strict=True))) for r in requests]
    if len(set(workspaces))!=len(workspaces): raise ValueError("Shared workspace needs serial reconciliation; duplicate rejected")
    # Full original contract, source, input and dependency checks; no reduced matcher or cached MATCH.
    plans=[] if a.stream_lanes else [matcher.match(r,registry) for r in requests]
    match_s=time.perf_counter()-began
    def execute(item):
        i,plan=item;t=time.perf_counter()
        proc=subprocess.Popen(plan["argv"],cwd=plan["cwd"],env={**os.environ,**plan["env"]},
            stdin=subprocess.DEVNULL,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
        out,err=proc.communicate()
        return {"index":i,"cwd":plan["cwd"],"pid":proc.pid,"start":t,"end":time.perf_counter(),
            "input_hashes":plan["input_hashes"],"source_hashes":plan["source_hashes"],
            "exit_code":proc.returncode,"stdout":out.decode("utf-8","replace"),
            "stderr":err.decode("utf-8","replace")}
    lane_metrics=[]
    if a.stream_lanes:
        if a.lane_root is None:raise ValueError("stream-lanes requires explicit lane-root")
        boundary=a.lane_root.resolve(strict=True);groups={}
        for i,request in enumerate(requests):
            if request.get("goal")!="files.archive_exact" or request.get("context")!="host":raise ValueError("Only original host archive streams admitted")
            lane=Path(request["workspace"]).resolve(strict=True).parent
            if lane.parent!=boundary:raise ValueError("Each stream must have one independent direct-child lane root")
            groups.setdefault(lane,[]).append({"index":i,"request":request})
        if len(groups)!=min(a.workers,len(requests)):raise ValueError("Stream roots must match selected lane count")
        worker=Path(__file__).with_name("archive_stream_worker.py")
        def run_stream(pair):
            lane,items=pair;packet=lane/"STREAM-TASKS.json"
            with packet.open("x",encoding="utf-8") as f:json.dump({"lane":str(lane),"library":str(a.library.resolve()),"items":items},f,ensure_ascii=False)
            proc=subprocess.run([registry["node"],registry["sandbox_runner"],"--workspace",str(lane),"--temp",registry["sandbox_temp"],
                "--mode","workspace-write","--",sys.executable,"-X","utf8",str(worker),"--plan",str(packet)],
                cwd=lane,env={**os.environ,"PYTHONUTF8":"1","PYTHONIOENCODING":"utf-8"},stdin=subprocess.DEVNULL,capture_output=True)
            result_path=lane/"STREAM-RESULTS.json"
            if not result_path.exists():raise RuntimeError(proc.stderr.decode("utf-8","replace"))
            metric=json.loads(result_path.read_text(encoding="utf-8"));metric["process_exit_code"]=proc.returncode
            return metric
        with concurrent.futures.ThreadPoolExecutor(max_workers=a.workers) as pool:
            lane_metrics=list(pool.map(run_stream,groups.items()))
        results=sorted([row for metric in lane_metrics for row in metric["results"]],key=lambda row:row["index"])
    elif a.lane_root is None:
        with concurrent.futures.ThreadPoolExecutor(max_workers=a.workers) as pool:
            results=list(pool.map(execute,enumerate(plans)))
    else:
        boundary=a.lane_root.resolve(strict=True)
        if any(r.get("goal")!="files.archive_exact" or r.get("context")!="host" for r in requests):
            raise ValueError("Lane reuse is admitted only for explicit host archive contracts")
        groups={}
        for i,(request,plan) in enumerate(zip(requests,plans)):
            lane=Path(plan["cwd"]).parent.resolve(strict=True)
            if lane.parent!=boundary:raise ValueError("Each lane must be a direct child of the authorized batch workspace")
            groups.setdefault(lane,[]).append({"index":i,"input_directory":request["input_directory"],"plan":plan})
        if len(groups)!=min(a.workers,len(plans)):raise ValueError("Distinct lane roots must match requested lane count")
        programme=a.library.resolve()/"assets/ready-flows/pi-native/artifact_recipe.py"
        worker=Path(__file__).with_name("archive_lane_worker.py")
        def run_lane(pair):
            lane,items=pair;packet=lane/"LANE-TASKS.json"
            expected=items[0]["plan"]["source_hashes"].get(str(programme))
            if expected is None:raise ValueError("Original archive not in verified source closure")
            with packet.open("x",encoding="utf-8") as f:json.dump({"lane":str(lane),"programme":str(programme),"sha256":expected,"items":items},f,ensure_ascii=False)
            proc=subprocess.run([registry["node"],registry["sandbox_runner"],"--workspace",str(lane),"--temp",registry["sandbox_temp"],
                "--mode","workspace-write","--",sys.executable,"-X","utf8",str(worker),"--plan",str(packet)],cwd=lane,
                env={**os.environ,**items[0]["plan"]["env"]},stdin=subprocess.DEVNULL,capture_output=True)
            if proc.returncode:raise RuntimeError(proc.stderr.decode("utf-8","replace"))
            return json.loads((lane/"LANE-RESULTS.json").read_text(encoding="utf-8"))
        with concurrent.futures.ThreadPoolExecutor(max_workers=a.workers) as pool:
            lanes=list(pool.map(run_lane,groups.items()))
        results=sorted([row for lane in lanes for row in lane],key=lambda row:row["index"])
    result={"status":"EXECUTED" if all(r["exit_code"]==0 for r in results) else "EXECUTION_FAILED",
        "stream_lanes":a.stream_lanes,"lane_metrics":lane_metrics,
        "workers":a.workers,"match_s":match_s,"elapsed_s":time.perf_counter()-began,"results":results,
        "acceptance":"Original business checks remain in each unchanged entry; independent delivery QA still required"}
    with a.result.open("x",encoding="utf-8") as f:json.dump(result,f,ensure_ascii=False,indent=2)
    print(json.dumps({"status":result["status"],"result":str(a.result)},ensure_ascii=True),flush=True)
    return 0 if result["status"]=="EXECUTED" else 1
if __name__=="__main__":
    try:sys.exit(main())
    except Exception as e:
        print(type(e).__name__+": "+str(e),file=sys.stderr);sys.exit(2)

